// Elegant placeholder illustrations until real photos are imported.
const PALETTE = {
  diffusers: ['#E9DFD0', '#1B1814', '#A9874F'], oils: ['#EADBD0', '#C9AD7A', '#7E6236'],
  perfumes: ['#DDE0D2', '#F7F2EA', '#A9874F'], hair: ['#F1E6DA', '#D8B98C', '#7E6236'],
  sticks: ['#E4DDD2', '#2A251F', '#C9AD7A'], candles: ['#EFE5D6', '#FFFDF9', '#A9874F'],
};
const SHAPES = {
  diffusers: (b, a) => `<rect x="70" y="80" width="60" height="120" rx="8" fill="${b}"/><rect x="70" y="80" width="60" height="10" fill="${a}"/><circle cx="100" cy="70" r="3" fill="${a}"/><path d="M100 64c-6-10 6-16 0-26" stroke="${a}" stroke-width="1.5" fill="none" opacity=".6"/>`,
  oils: (b, a) => `<rect x="76" y="95" width="48" height="105" rx="6" fill="${b}" opacity=".9"/><rect x="88" y="70" width="24" height="26" fill="#1B1814"/><rect x="82" y="130" width="36" height="34" fill="#FFFDF9" opacity=".85"/><line x1="88" y1="147" x2="112" y2="147" stroke="${a}"/>`,
  perfumes: (b, a) => `<rect x="70" y="100" width="60" height="100" rx="4" fill="${b}" stroke="${a}" stroke-width="1.2"/><rect x="92" y="78" width="16" height="22" fill="${a}"/><rect x="86" y="66" width="28" height="14" fill="#1B1814"/><text x="100" y="155" text-anchor="middle" font-family="Georgia" font-size="11" fill="${a}" letter-spacing="2">SAY</text>`,
  hair: (b, a) => `<rect x="78" y="88" width="44" height="112" rx="22" fill="${b}"/><rect x="90" y="66" width="20" height="24" fill="${a}"/><rect x="84" y="135" width="32" height="1.5" fill="#FFFDF9"/>`,
  sticks: (b, a) => `<path d="M72 200v-60q0-30 28-30t28 30v60z" fill="${b}"/>${[0, 1, 2, 3, 4].map((i) => `<line x1="${94 + i * 3}" y1="112" x2="${70 + i * 15}" y2="30" stroke="${a}" stroke-width="2"/>`).join('')}`,
  candles: (b, a) => `<rect x="62" y="120" width="76" height="80" rx="6" fill="${b}" stroke="${a}" stroke-width="1"/><ellipse cx="100" cy="120" rx="38" ry="6" fill="#efe3cf"/><line x1="100" y1="120" x2="100" y2="106" stroke="#1B1814" stroke-width="2"/><path d="M100 104c-6-8 0-16 0-20 0 4 6 12 0 20z" fill="${a}"/>`,
};
export function artSVG(p, cls = '') {
  const [bg, body, acc] = PALETTE[p.cat] || PALETTE.oils;
  const shape = (SHAPES[p.cat] || SHAPES.oils)(body, acc);
  return `<svg class="${cls}" viewBox="0 0 200 250" role="img" aria-label="${(p.name?.he || '').replace(/[<>"&]/g, '')}" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid slice"><rect width="200" height="250" fill="${bg}"/><path d="M40 250V120a60 60 0 01120 0v130" fill="#fffdf9" opacity=".45"/><ellipse cx="100" cy="202" rx="52" ry="5" fill="#000" opacity=".08"/>${shape}</svg>`;
}
export function catIcon(id) {
  const fake = { cat: id, name: { he: '' } };
  return artSVG(fake).replace('<svg ', '<svg aria-hidden="true" ').replace(/role="img" aria-label="[^"]*"/, '');
}
